INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What does ''picks per inch'' (PPI) measure in a woven fabric?', '["The number of weft (filling) yarns per inch of fabric length","The number of warp yarns per inch of fabric width","The twist level of the weft yarn","The exact color count used in the fabric"]'::jsonb, 'The number of weft (filling) yarns per inch of fabric length', 'Picks per inch (PPI) counts how many weft insertions occur per inch along the fabric''s length — a key density parameter alongside ends per inch (EPI, the warp count per inch of width).', 1, '{"picks-per-inch"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What does ''ends per inch'' (EPI) measure in a woven fabric?', '["The number of warp yarns per inch of fabric width","The number of weft yarns per inch of fabric length","The number of colors used in the fabric design","The exact weight of the fabric per square meter"]'::jsonb, 'The number of warp yarns per inch of fabric width', 'Ends per inch (EPI) counts the number of warp threads packed into one inch of fabric width — combined with PPI, it defines the fabric''s overall thread density.', 1, '{"ends-per-inch"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A fabric has higher EPI and PPI (more threads packed per inch) than another fabric of the same yarn count. What does this generally indicate about the first fabric?', '["It is more densely woven/compact, generally heavier and potentially more durable","It must automatically be a different color","It has fewer warp yarns overall despite the higher EPI number","Thread density has no relationship to fabric weight or compactness"]'::jsonb, 'It is more densely woven/compact, generally heavier and potentially more durable', 'Higher EPI/PPI at the same yarn count means more yarn packed into the same fabric area — resulting in a denser, typically heavier, and often more durable/wind-resistant fabric (though also stiffer and more expensive to produce).', 2, '{"fabric-density"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What is ''cover factor'' in woven fabric design?', '["A calculated value representing how much of the fabric''s area is covered by yarn versus open space, based on yarn count and thread density","The exact percentage of cotton versus synthetic fiber in a blend","The color depth achieved during dyeing","The width of the fabric selvedge only"]'::jsonb, 'A calculated value representing how much of the fabric''s area is covered by yarn versus open space, based on yarn count and thread density', 'Cover factor combines yarn count (thickness) and thread density (EPI/PPI) into a single number indicating how tightly the fabric surface is covered by yarn — used to compare/design fabrics of different constructions on a common basis.', 2, '{"cover-factor"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Why does a fabric with a very high cover factor (extremely dense weave) tend to have reduced air permeability?', '["There is less open space between yarns for air to pass through, since the yarns nearly or fully cover the fabric surface","Cover factor has no relationship to air permeability at all","High cover factor fabrics always use synthetic fiber exclusively","Air permeability depends only on fabric color, not thread density"]'::jsonb, 'There is less open space between yarns for air to pass through, since the yarns nearly or fully cover the fabric surface', 'As cover factor increases, the open pore spaces between warp and weft yarns shrink, directly reducing the fabric''s air permeability — this tradeoff is why very tightly woven fabrics (e.g., ripstop, ballistic nylon) feel less breathable.', 2, '{"cover-factor","air-permeability"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is the function of a ''dobby'' mechanism on a loom?', '["It controls a moderate number of heald frames independently to weave small, geometric patterned weaves beyond plain/twill/satin","It is used only to insert weft yarn, not for pattern control","It replaces the need for any warp beam","It only works for weaving solid, one-color fabric with no pattern"]'::jsonb, 'It controls a moderate number of heald frames independently to weave small, geometric patterned weaves beyond plain/twill/satin', 'A dobby mechanism allows independent control of a moderate number of heald frames (typically up to 20-30), enabling small, repeating geometric patterns (like birdseye, honeycomb, or small check designs) beyond basic weaves.', 1, '{"dobby-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is the function of a ''jacquard'' mechanism on a loom?', '["It controls each individual warp yarn independently (via punched cards or electronic control), enabling large, complex, non-repeating patterns","It only controls a small number of heald frames, like a dobby","It is used exclusively for inserting weft yarn","It eliminates the need for shedding motion entirely"]'::jsonb, 'It controls each individual warp yarn independently (via punched cards or electronic control), enabling large, complex, non-repeating patterns', 'Jacquard mechanisms control each warp yarn (or small group) individually, rather than in frame groups like a dobby — this allows weaving large, intricate, picture-like patterns (e.g., brocade, elaborate florals) impossible on dobby or plain looms.', 1, '{"jacquard-loom"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Why can a jacquard loom weave far more complex patterns than a dobby loom?', '["Jacquard controls warp yarns individually, while dobby controls them only in grouped frames, limiting dobby pattern resolution/complexity","Jacquard looms don''t use any warp yarn at all","Dobby looms can weave unlimited pattern complexity, same as jacquard","Jacquard looms only work with weft yarn control, not warp"]'::jsonb, 'Jacquard controls warp yarns individually, while dobby controls them only in grouped frames, limiting dobby pattern resolution/complexity', 'Since a dobby''s heald frames each move a whole group of warp threads together, pattern resolution is limited to how those groups are organized; jacquard''s individual-yarn control allows far finer, more complex, and larger-repeat pattern design.', 2, '{"jacquard-vs-dobby"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is a ''heald frame'' (harness) in dobby/cam weaving?', '["A frame holding multiple healds that moves up or down together as a single shedding unit","The final rolled fabric package","The device that measures fabric width during weaving","A chemical treatment applied to warp yarn"]'::jsonb, 'A frame holding multiple healds that moves up or down together as a single shedding unit', 'A heald frame (harness) holds a group of healds and moves as one unit during shedding; the warp yarns threaded through healds on the same frame all rise or fall together, defining which threads interlace at each pick.', 1, '{"heald-frame"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is ''reed count'' (or reed number) used to specify?', '["The number of dents (spaces) per unit width in the reed, which relates to warp thread density","The total number of picks inserted per minute","The exact twist level of the warp yarn","The color sequence of the warp yarns"]'::jsonb, 'The number of dents (spaces) per unit width in the reed, which relates to warp thread density', 'Reed count specifies how many dents (gaps between wires) exist per unit width (e.g., per inch or per 10 cm); combined with how many warp ends are drawn through each dent, it determines the warp''s EPI (ends per inch).', 1, '{"reed-count"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is a ''drop wire'' (warp stop motion) used for in weaving?', '["To automatically detect a broken warp thread and stop the loom, preventing a major fabric defect","To insert extra color into the weft yarn","To measure the exact width of the finished fabric","To apply size/starch coating to the warp"]'::jsonb, 'To automatically detect a broken warp thread and stop the loom, preventing a major fabric defect', 'Each warp thread passes through a small drop wire; if that thread breaks, the wire falls and completes an electrical circuit (or mechanically triggers a stop), immediately halting the loom before a defect (missing end) can spread through many picks.', 1, '{"drop-wire","warp-stop-motion"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Why is an automatic warp stop motion (drop wires) critical for weaving quality, especially on high-speed modern looms?', '["Without it, a broken warp end would go undetected for many picks, creating a long, visible fabric defect before anyone notices","It has no real quality impact and exists only for operator convenience","It only matters for hand looms, not power looms","It prevents weft breaks, not warp breaks"]'::jsonb, 'Without it, a broken warp end would go undetected for many picks, creating a long, visible fabric defect before anyone notices', 'At high loom speeds, many picks are inserted per minute; if a warp break isn''t caught immediately, a long section of fabric with a missing/faulty end is woven before manual detection — automatic stop motion prevents this costly quality loss.', 2, '{"warp-stop-motion","quality"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is a ''weft stop motion'' designed to detect?', '["A broken or exhausted weft yarn, stopping the loom before a pick is missed","A broken warp thread only","The exact fabric width being produced","The color of the yarn being used"]'::jsonb, 'A broken or exhausted weft yarn, stopping the loom before a pick is missed', 'Weft stop motion (mechanical feeler or electronic sensor) detects when weft yarn breaks or runs out mid-pick, stopping the loom immediately to prevent a ''missing pick'' defect in the fabric.', 1, '{"weft-stop-motion"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What causes the fabric defect known as a ''reed mark'' (or reed streak)?', '["Damaged, bent, or worn reed dents causing certain warp threads to be spaced incorrectly, creating a visible line/streak in the fabric","Excess dye applied unevenly during finishing","Incorrect twist direction in the weft yarn","The wrong fiber type being used in the weft"]'::jsonb, 'Damaged, bent, or worn reed dents causing certain warp threads to be spaced incorrectly, creating a visible line/streak in the fabric', 'If reed dents are bent, worn, or clogged, warp threads at that position get pushed together or spread apart abnormally, creating a persistent visible streak running the length of the fabric wherever that reed section is used.', 2, '{"reed-mark","weaving-defects"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What fabric defect is typically caused by uneven let-off/take-up tension, appearing as alternating bands of tight and loose weft density?', '["Weft bar (barré)","Reed mark","Selvedge curl","Slub in the yarn"]'::jsonb, 'Weft bar (barré)', 'Weft bar (barré) appears as visible horizontal bands of varying density/shade across the fabric width, often caused by inconsistent take-up/let-off tension or periodic weft tension variation, creating alternating tight and loose picks.', 2, '{"weft-bar","weaving-defects"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Why do woven fabrics typically show more strength/rigidity along the warp direction than diagonally (on the bias)?', '["Warp and weft yarns interlace at fixed right angles, providing strong resistance to stretching along their own axes but far less resistance to shear/distortion at other angles","Warp yarns are always chemically stronger fiber than weft yarns","Bias direction strength has no relationship to the weave''s yarn interlacing geometry","Woven fabrics have identical mechanical properties in every direction"]'::jsonb, 'Warp and weft yarns interlace at fixed right angles, providing strong resistance to stretching along their own axes but far less resistance to shear/distortion at other angles', 'Since woven structure locks warp and weft at roughly 90°, pulling along either yarn direction is resisted directly by that yarn''s tensile strength; pulling on the bias (diagonal) instead causes the whole grid to shear/rack, which is resisted only by inter-yarn friction — much weaker, giving woven fabric its characteristic bias stretch.', 2, '{"bias-stretch","fabric-mechanics"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'What is the purpose of ''temples'' (or temple rings) mounted near the fell of the cloth during weaving?', '["To hold the fabric at its full woven width, preventing it from narrowing (contracting) due to weft tension","To insert additional color into the weft","To measure the exact fabric length woven so far","To apply finishing chemicals during weaving"]'::jsonb, 'To hold the fabric at its full woven width, preventing it from narrowing (contracting) due to weft tension', 'As weft is beaten in under tension, fabric tends to contract in width; temples (spiked rings or similar devices) grip the fabric edges near the fell and hold it at the intended weaving width, preventing width contraction and edge damage.', 2, '{"temples","fabric-width-control"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A weaving mill notices a repeating pattern of missing/faulty picks at regular pick intervals across many meters of fabric. What is a likely mechanical cause to investigate?', '["A malfunctioning or improperly timed weft insertion/stop-motion mechanism repeating a fault on a fixed machine cycle","The dye lot used for the yarn","The fiber content of the warp yarn","The width of the fabric being woven"]'::jsonb, 'A malfunctioning or improperly timed weft insertion/stop-motion mechanism repeating a fault on a fixed machine cycle', 'A defect recurring at REGULAR pick intervals strongly suggests a mechanical/timing issue tied to a specific machine cycle (e.g., a faulty gripper, timing cam, or stop-motion component) rather than a random yarn or material issue.', 2, '{"weaving-troubleshooting"}'::text[]);
